### 5. Main Image Generation Service
This is the class that the rest of your application will interact with. It receives the settings in the constructor and exposes the generation method.

```typescript /src/services/image-generation/ImageGenerationService.ts
import { ProjectSettings, AIModelSettings, ImageGenerationResponse, AIProvider } from './types';
import { BaseImageProvider } from './providers/BaseImageProvider';
import { OpenAIProvider } from './providers/OpenAIProvider';
import { GeminiNanoProvider } from './providers/GeminiNanoProvider';

export class ImageGenerationService {
  private provider: BaseImageProvider;

  constructor(
    private projectSettings: ProjectSettings,
    private modelSettings: AIModelSettings
  ) {
    this.provider = this.createProvider();
  }

  private createProvider(): BaseImageProvider {
    switch (this.modelSettings.provider) {
      case 'openai':
        return new OpenAIProvider(this.projectSettings, this.modelSettings);
      case 'gemini-nano':
        return new GeminiNanoProvider(this.projectSettings, this.modelSettings);
      default:
        throw new Error(`Provider ${this.modelSettings.provider} is not supported.`);
    }
  }

  /**
   * Main method to generate an image
   */
  public async generate(prompt: string): Promise<ImageGenerationResponse> {
    try {
      return await this.provider.generateImage(prompt);
    } catch (error) {
      console.error("Image generation failed:", error);
      throw error;
    }
  }
}
```

